/** @type {import('tailwindcss').Config} */
// Colors come from CSS variables in src/theme.css (generated by scripts/gen-theme.cjs),
// so the light app and the dark photo viewers (.theme-dark) share the same class names.
const STOPS = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950];
const themed = name => Object.fromEntries(STOPS.map(stop => [stop, `rgb(var(--c-${name}-${stop}) / <alpha-value>)`]));

export default {
  content: [
    "./client/index.html",
    "./client/src/**/*.{js,ts,jsx,tsx}",
    "./index.html",
    "./src/**/*.{js,ts,jsx,tsx}",
  ],
  theme: {
    extend: {
      colors: {
        slate: themed('slate'),
        stone: themed('stone'),
        rose: themed('rose'),
        emerald: themed('emerald'),
        amber: themed('amber'),
        blue: themed('blue'),
        purple: themed('purple'),
        red: themed('red'),
        sky: themed('sky'),
        // "white" was the old dark UI's main text color: it follows the theme.
        // Use "paper" for text that must stay white (on photos, on solid buttons).
        white: 'rgb(var(--c-white) / <alpha-value>)',
        paper: '#ffffff',
        studio: {
          bg: 'var(--studio-bg)',
          panel: 'var(--studio-panel)',
          raised: 'var(--studio-raised)',
          line: 'var(--studio-line)',
          text: 'var(--studio-text)',
          muted: 'var(--studio-muted)',
          accent: 'var(--studio-accent)',
          'accent-soft': 'var(--studio-accent-soft)',
          'accent-text': 'var(--studio-accent-text)',
        },
      },
    },
  },
  plugins: [],
}
